<?php require_once '../includes/auth.php'; require_role('admin'); $page_title='Audit Logs'; include '../includes/header.php'; include '../includes/sidebar.php'; $q=mysqli_query($conn,"SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200"); ?>
